import test from 'node:test';import assert from 'node:assert/strict';import {mkdtempSync,rmSync} from 'node:fs';import {tmpdir} from 'node:os';import {join} from 'node:path';import http from 'node:http';
import {openStore} from '../server/store.mjs';import {createService} from '../server/service.mjs';import {createHandler} from '../server/index.mjs';import {openSecurityDirectory,DIRECTORY_SOURCES,parseDirectoryFile} from '../server/security-directory.mjs';import {companyEntitiesPacket} from '../server/company-entities.mjs';import {digest} from '../server/codex-research.mjs';
const at=Date.parse('2026-10-03T01:00:00Z');
const nasdaq=['ACME|Acme Laboratories Inc. - Common Stock|Q|N|N|100|N|N','NVDA|NVIDIA Corporation - Common Stock|Q|N|N|100|N|N','TEST|Synthetic Test Common Stock|Q|Y|N|100|N|N','FUND|Synthetic Common Stock Fund|Q|N|N|100|Y|N','PREF|Synthetic Preferred Stock|Q|N|N|100|N|N'];
const other=['OTHER|Other Holdings plc Ordinary Shares|N|OTHER|N|100|N|OTHER'];
const file=(s,rows,date='1002202618:01')=>[s.header,...rows,'File Creation Time: '+date+'|'.repeat(s.id==='other'?6:7)].join('\r\n')+'\r\n';
function fixture(options={}){const store=openStore(options.path||':memory:');let date='1002202618:01',broken=false,calls=0;const fetcher=async url=>{calls++;if(broken)throw Error('private diagnostic');const s=DIRECTORY_SOURCES.find(s=>s.url===url);assert.ok(s);return new Response(file(s,s.id==='nasdaq'?nasdaq:other,date));};const service=createService(store,{mode:options.mode||'research',now:()=>at,fetcher,...options});return {store,service,d:service.securityDirectory,get calls(){return calls;},date:d=>date=d,break:()=>broken=true,async close(){await service.close();store.close();}};}
async function refresh(f,id='directory-request-00001'){f.d.refresh({requestId:id});return f.d.wait();}
test('official formats parse all rows, filter unsupported types and preserve raw fields and generation date',()=>{const p=parseDirectoryFile(DIRECTORY_SOURCES[0],file(DIRECTORY_SOURCES[0],nasdaq));assert.equal(p.sourceDate,'2026-10-02');assert.equal(p.entries.length,5);assert.equal(p.entries.filter(e=>e.eligible).length,2);assert.equal(p.entries[0].rawFields['Financial Status'],'N');assert.equal(parseDirectoryFile(DIRECTORY_SOURCES[1],file(DIRECTORY_SOURCES[1],other)).entries[0].venue,'XNYS');for(const raw of [file(DIRECTORY_SOURCES[0],[nasdaq[0],nasdaq[0]]),file(DIRECTORY_SOURCES[0],nasdaq).replace('File Creation Time:','broken'),file(DIRECTORY_SOURCES[0],nasdaq,'0230202618:01'),file(DIRECTORY_SOURCES[0],nasdaq).replace('|N|N|100','|N|N|0'),file(DIRECTORY_SOURCES[0],nasdaq).replace('Symbol|','Wrong|')])assert.throws(()=>parseDirectoryFile(DIRECTORY_SOURCES[0],raw));});
test('refresh is explicit, idempotent and versioned; old snapshots are queryable and failed updates preserve them',async()=>{const f=fixture();try{assert.equal(f.calls,0);assert.equal(f.d.search().total,0);const first=await refresh(f);assert.equal(first.current.counts.rows,6);assert.equal(first.current.counts.eligible,3);assert.equal(f.calls,2);await refresh(f);assert.equal(f.calls,2);await refresh(f,'directory-request-00002');assert.equal(f.d.status().history.length,1);const id=first.current.id;f.date('1003202601:00');await refresh(f,'directory-request-00003');assert.equal(f.d.status().history.length,2);assert.notEqual(f.d.status().current.id,id);assert.equal(f.d.search({q:'acme',snapshotId:id}).items[0].directorySnapshotId,id);f.break();const failed=await refresh(f,'directory-request-00004');assert.equal(failed.attempts[0].status,'failed');assert.equal(failed.history.length,2);assert.ok(!JSON.stringify(failed).includes('private diagnostic'));}finally{await f.close();}});
test('date regression and a partial upstream failure never replace current directory',async()=>{const f=fixture();try{await refresh(f);const id=f.d.status().current.id;f.date('1001202618:01');await refresh(f,'directory-regression-0001');assert.equal(f.d.status().current.id,id);assert.equal(f.d.status().attempts[0].status,'failed');assert.throws(()=>f.d.search({offset:-1}));assert.throws(()=>f.d.search({extra:true}));assert.throws(()=>f.d.search({snapshotId:'missing'}));}finally{await f.close();}});
test('offline, restore, invalid requests and cross-instance lease block unintended updates',async()=>{const f=fixture();const d2=openSecurityDirectory(f.store,{now:()=>at});try{f.d.refresh({requestId:'directory-request-00001'});assert.throws(()=>d2.refresh({requestId:'directory-request-00002'}),/正在更新/);await f.d.wait();assert.throws(()=>f.d.refresh({requestId:'short'}));f.store.db.prepare("INSERT OR REPLACE INTO settings VALUES('restore_review_required','1')").run();assert.throws(()=>f.d.refresh({requestId:'directory-request-00003'}),/恢复/);}finally{await d2.close();await f.close();}const offline=fixture({mode:'demo'});try{assert.throws(()=>offline.d.refresh({requestId:'directory-request-00001'}),/当前模式/);assert.equal(offline.calls,0);}finally{await offline.close();}});
test('bounded name recall includes previously unknown companies, explicit symbols and known translations without sending full directory',async()=>{const f=fixture();try{await refresh(f);assert.deepEqual(f.d.selection('Acme Laboratories discusses work. 英伟达发布信息。').entries.map(c=>c.symbol),['ACME.US','NVDA.US']);assert.deepEqual(f.d.selection('NYSE: OTHER is mentioned.').entries.map(c=>c.symbol),['OTHER.US']);assert.equal(f.d.selection('ordinary fruit and a fictional institution').entries.length,0);assert.equal(f.d.selection('Acme Laboratories').basis.totalEligible,3);}finally{await f.close();}});
test('new snapshot freezes into model packet, allows a reviewed unfamiliar company and makes older candidates stale without rewriting history',async()=>{const config={binary:'/test/codex',model:'test',timeoutMs:1000};const f=fixture({modelConfig:config,companyEntityRunner:async p=>{const resolution={mentions:[{name:'Acme Laboratories',quote:'Acme Laboratories discusses work.',quoteField:'body',entityType:'company',resolution:'candidate',symbols:['ACME.US'],reason:'合成名称对应，尚待核对'}],scopeNote:'合成材料',missingEvidence:[]},rawOutput=JSON.stringify(resolution);return {status:'candidate',reviewStatus:'unreviewed',resolution,rawOutput,trace:{model:'test',inputHash:p.inputHash,outputHash:digest(rawOutput)}};}});try{await refresh(f);const r=f.service.research;let t=r.create({title:'合成新目录主体研究',summary:'仅测试身份流程'});t=r.saveMaterial(t.id,{version:t.version,title:'合成目录材料',sourceName:'合成',url:'https://news.acme.com/directory',body:'Acme Laboratories discusses work.',scope:'excerpt',stance:'unverified',family:'other',step:'fact',interpretation:'合成'});const m=r.materialList(t.id).materials[0],ref={version:t.version,materialId:m.id,revision:m.revision},p=companyEntitiesPacket(f.store,r,t.id,ref);assert.ok(p.input.directory.some(c=>c.symbol==='ACME.US'));assert.ok(!p.input.directory.some(c=>c.symbol==='OTHER.US'));assert.equal(p.input.directorySnapshot.selected,1);const a=f.service.companyEntities.start(t.id,{...ref,requestId:'directory-model-00001'});await f.service.companyEntities.wait(a.id);f.service.companyEntities.decide(t.id,a.id,{mentionIndex:0,version:0,action:'link',symbol:'ACME.US',note:'合成核对',topicVersion:t.version});let c=r.get(t.id).companies[0];assert.equal(c.identityStatus,'directory-snapshot');assert.match(c.name,/Acme/);const basis=c.entityResolution;r.addCompany(t.id,{version:r.get(t.id).version,replace:true,symbol:'acme.us',note:'修改合成说明'});c=r.get(t.id).companies[0];assert.equal(c.identityStatus,'directory-snapshot');assert.deepEqual(c.entityResolution,basis);const old=f.service.companyEntities.get(t.id,a.id).packet;f.date('1003202601:00');await refresh(f,'directory-request-00002');assert.equal(f.service.companyEntities.get(t.id,a.id).stale,true);assert.deepEqual(f.service.companyEntities.get(t.id,a.id).packet,old);assert.deepEqual(r.get(t.id).companies[0].entityResolution,basis);}finally{await f.close();}});
test('snapshots and attempts survive restart with original raw data and integrity verification',async()=>{const dir=mkdtempSync(join(tmpdir(),'security-dir-')),path=join(dir,'test.sqlite'),f=fixture({path});try{await refresh(f);const before=f.d.status(),raw=f.d.current().sources[0].raw;await f.close();const s=openStore(path),d=openSecurityDirectory(s,{now:()=>at});try{assert.deepEqual(d.status(),before);assert.equal(d.current().sources[0].raw,raw);const id=before.current.id,v=JSON.parse(s.db.prepare('SELECT payload FROM security_directory_snapshots WHERE id=?').get(id).payload);v.entries[0].name='tampered';s.db.prepare('UPDATE security_directory_snapshots SET payload=? WHERE id=?').run(JSON.stringify(v),id);assert.throws(()=>d.search({snapshotId:id}),/校验/);}finally{await d.close();s.close();}}finally{rmSync(dir,{recursive:true,force:true});}});
test('HTTP exposes bounded query and explicit refresh; untrusted origins and extra source URLs fail',async()=>{const f=fixture(),server=http.createServer();await new Promise(r=>server.listen(0,'127.0.0.1',r));const port=server.address().port;server.on('request',createHandler(f.store,f.service,{apiPort:port,frontendPort:port}));const base=`http://127.0.0.1:${port}/api/security-directory`;const post=d=>fetch(base+'/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});try{assert.equal((await fetch(base)).status,200);assert.equal(f.calls,0);assert.equal((await post({requestId:'directory-request-00001'})).status,202);await f.d.wait();const data=await(await fetch(base+'?q=acme')).json();assert.equal(data.search.total,1);assert.equal(data.current.sources[0].raw,undefined);assert.equal((await post({requestId:'directory-request-00002',url:'https://evil.invalid'})).status,400);assert.equal((await fetch(base,{headers:{Origin:'https://evil.invalid'}})).status,403);}finally{await new Promise(r=>server.close(r));await f.close();}});
test('refresh cancellation and transaction failure preserve earlier snapshots and release the lease',async()=>{const f=fixture();try{await refresh(f);const id=f.d.status().current.id;f.store.db.exec("CREATE TRIGGER reject_directory BEFORE INSERT ON security_directory_snapshots BEGIN SELECT RAISE(ABORT,'synthetic failure'); END");f.date('1003202601:00');await refresh(f,'directory-rollback-00001');assert.equal(f.d.status().current.id,id);assert.equal(f.d.status().attempts[0].status,'failed');assert.equal(f.d.status().running,false);}finally{await f.close();}const s=openStore(':memory:'),d=openSecurityDirectory(s,{fetcher:(_url,{signal})=>new Promise((_resolve,reject)=>signal.addEventListener('abort',()=>reject(Error('cancelled'))))});try{d.refresh({requestId:'directory-cancel-00001'});await d.close();assert.equal(d.status().attempts[0].status,'failed');assert.equal(d.status().running,false);assert.equal(d.status().history.length,0);}finally{s.close();}});
test('expired pending attempts remain interrupted and recalled candidates are capped with an explicit omitted count',async()=>{const s=openStore(':memory:'),rows=Array.from({length:85},(_,i)=>`CO${String.fromCharCode(65+Math.floor(i/26))}${String.fromCharCode(65+i%26)}|Synthetic Enterprise ${i} Inc. - Common Stock|Q|N|N|100|N|N`),d=openSecurityDirectory(s,{now:()=>at,fetcher:async url=>{const source=DIRECTORY_SOURCES.find(s=>s.url===url);return new Response(file(source,source.id==='nasdaq'?rows:other));}});try{s.db.prepare('INSERT INTO security_directory_attempts VALUES(?,?,?)').run('old','running',JSON.stringify({id:'old',status:'running',startedAt:'2026-10-01T00:00:00Z'}));assert.equal(d.status().attempts[0].status,'interrupted');d.refresh({requestId:'directory-bound-00001'});await d.wait();const selected=d.selection(Array.from({length:85},(_,i)=>`Synthetic Enterprise ${i}`).join('. '));assert.equal(selected.entries.length,80);assert.equal(selected.basis.matched,85);assert.equal(selected.basis.omitted,5);}finally{await d.close();s.close();}});
